<?php
namespace App\Http\Controllers\Patient;
use App\Http\Controllers\Controller;
use App\Models\Appointment;
use App\Models\AppointmentPayment;
use App\Models\SiteSetting;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Http;
use Illuminate\Support\Facades\Log;
use Illuminate\Support\Facades\DB;
class SslCommerzController extends Controller {
 private function settings():array{return ['enabled'=>(string)SiteSetting::valueFor('sslcommerz_enabled','0'),'environment'=>(string)SiteSetting::valueFor('sslcommerz_environment','sandbox'),'store_id'=>(string)SiteSetting::valueFor('sslcommerz_store_id',''),'store_passwd'=>(string)SiteSetting::valueFor('sslcommerz_store_passwd','')];}
 private function gatewayBase(array $s):string{return $s['environment']==='live'?'https://securepay.sslcommerz.com':'https://sandbox.sslcommerz.com';}
 private function validatorBase(array $s):string{return $s['environment']==='live'?'https://securepay.sslcommerz.com':'https://sandbox.sslcommerz.com';}
 public function initiate(Appointment $appointment){abort_unless((int)$appointment->patient_id===(int)auth()->id(),404);abort_unless(!in_array($appointment->status,['cancelled','rejected']) && !$appointment->fee_waived && (float)$appointment->fee>=10 && $appointment->payment_status!=='paid',422,'This appointment is not payable online.');$s=$this->settings();if ($s['enabled'] !== '1' || trim($s['store_id']) === '' || trim($s['store_passwd']) === '') { return redirect()->route('patient.payments.create', $appointment)->withErrors(['payment' => 'SSLCommerz is not configured yet. The clinic administrator must enable online payments and save the Sandbox Store ID and Store Password in Admin → Payment Settings.']); }$payment=AppointmentPayment::create(['appointment_id'=>$appointment->id,'patient_id'=>auth()->id(),'method'=>'sslcommerz','amount'=>$appointment->fee,'status'=>'pending','patient_note'=>'SSLCommerz '.strtoupper($s['environment']).' checkout']);$tranId='DOC'.$payment->id.'-'.strtoupper(bin2hex(random_bytes(5)));$payment->update(['transaction_reference'=>$tranId]);$user=auth()->user();$payload=['store_id'=>$s['store_id'],'store_passwd'=>$s['store_passwd'],'total_amount'=>number_format((float)$appointment->fee,2,'.',''),'currency'=>'BDT','tran_id'=>$tranId,'product_category'=>'healthcare','success_url'=>route('sslcommerz.success'),'fail_url'=>route('sslcommerz.fail'),'cancel_url'=>route('sslcommerz.cancel'),'ipn_url'=>url('/api/sslcommerz/ipn'),'cus_name'=>$user->name,'cus_email'=>$user->email?:'patient@example.com','cus_add1'=>'Bangladesh','cus_city'=>'Dhaka','cus_postcode'=>'1000','cus_country'=>'Bangladesh','cus_phone'=>$user->phone?:'01700000000','shipping_method'=>'NO','ship_name'=>$user->name,'ship_add1'=>'Bangladesh','ship_city'=>'Dhaka','ship_postcode'=>'1000','ship_country'=>'Bangladesh','num_of_item'=>1,'product_name'=>'Doctor appointment '.$appointment->appointment_code,'product_profile'=>'general'];try{$response=Http::asForm()->timeout(20)->post($this->gatewayBase($s).'/gwprocess/v4/api.php',$payload);$body=$response->json();$gatewayUrl=(string)($body['GatewayPageURL']??'');$gatewayHost=strtolower((string)(parse_url($gatewayUrl,PHP_URL_HOST)??''));$validGatewayHost=$gatewayHost==='sslcommerz.com'||str_ends_with($gatewayHost,'.sslcommerz.com');if($response->successful() && $gatewayUrl!=='' && filter_var($gatewayUrl,FILTER_VALIDATE_URL) && in_array(strtolower((string)parse_url($gatewayUrl,PHP_URL_SCHEME)),['https'],true) && $validGatewayHost)return redirect()->away($gatewayUrl);$reason=trim(strip_tags((string)($body['failedreason']??$body['status']??'Gateway did not return a valid GatewayPageURL.')));if($reason==='')$reason='Gateway did not return a valid GatewayPageURL.';$reason=substr($reason,0,180);Log::warning('SSLCommerz initiation failed',['http_status'=>$response->status(),'gateway_status'=>$body['status']??null,'reason'=>$reason,'response_keys'=>is_array($body)?array_keys($body):[],'environment'=>$s['environment']]);$payment->update(['status'=>'failed']);return redirect()->route('patient.payments.create',$appointment)->withErrors(['payment'=>'SSLCommerz checkout failed (HTTP '.$response->status().'): '.$reason.' Check that the selected environment matches the Store ID and Store Password.']);}catch(\Throwable $e){report($e);$payment->update(['status'=>'failed']);return redirect()->route('patient.payments.create',$appointment)->withErrors(['payment'=>'Could not connect to SSLCommerz. Try again later.']);}}
 public function success(Request $request){$result=$this->validateAndUpdate($request);return redirect()->route('patient.payments.index')->with($result?'success':'error',$result?'SSLCommerz payment verified successfully.':'Payment could not be verified. Please contact the clinic before trying again.');}
 public function fail(Request $request){$this->markFailure($request,'failed');return redirect()->route('patient.payments.index')->with('error','SSLCommerz payment failed. No paid status was recorded.');}
 public function cancel(Request $request){$this->markFailure($request,'cancelled');return redirect()->route('patient.payments.index')->with('error','Payment was cancelled.');}
 public function ipn(Request $request){if(($request->input('status')??'')!=='VALID')return response()->noContent();$ok=$this->validateAndUpdate($request);return response()->json(['received'=>true,'validated'=>$ok],$ok?200:422);}
 private function validateAndUpdate(Request $request):bool{$tranId=(string)$request->input('tran_id','');$payment=AppointmentPayment::where('method','sslcommerz')->where('transaction_reference',$tranId)->first();if(!$payment || !$request->filled('val_id'))return false;$s=$this->settings();try{$response=Http::timeout(20)->get($this->validatorBase($s).'/validator/api/validationserverAPI.php',['val_id'=>$request->input('val_id'),'store_id'=>$s['store_id'],'store_passwd'=>$s['store_passwd'],'format'=>'json']);$data=$response->json();if(!$response->successful() || !is_array($data) || !in_array($data['status']??'', ['VALID','VALIDATED'],true) || (string)($data['tran_id']??'')!==$tranId || abs((float)($data['amount']??0)-(float)$payment->amount)>0.01 || strtoupper((string)($data['currency']??'BDT'))!=='BDT')return false;if((int)($data['risk_level']??0)===1){Log::warning('SSLCommerz risk payment held for review',['payment_id'=>$payment->id,'tran_id'=>$tranId]);return false;}DB::transaction(function()use($payment,$data){$locked=AppointmentPayment::whereKey($payment->id)->lockForUpdate()->firstOrFail();if($locked->status==='verified')return;$locked->update(['status'=>'verified','review_note'=>'SSLCommerz verified: '.($data['bank_tran_id']??$data['val_id']??'validated'),'reviewed_at'=>now()]);$locked->appointment()->update(['payment_status'=>'paid']);});return true;}catch(\Throwable $e){report($e);return false;}}
 private function markFailure(Request $request,string $status):void{$id=(string)$request->input('tran_id','');if($id==='')return;AppointmentPayment::where('method','sslcommerz')->where('transaction_reference',$id)->where('status','pending')->update(['status'=>$status]);}
}
